"""MUKMAP — Internationalisation. Dictionnaire central des libellés d'interface."""

LANGUES = (
    ('fr', 'Français'),
    ('en', 'English'),
    ('sw', 'Kiswahili'),
    ('ln', 'Lingála'),
    ('pt', 'Português'),
    ('zh', '中文'),
)

LANGUE_PAR_DEFAUT = 'fr'


def traduire(lang, cle):
    """Traduit une clé dans une langue (retourne la clé si inconnue)."""
    d = TRADUCTIONS.get(cle) or {}
    return d.get(lang) or d.get(LANGUE_PAR_DEFAUT) or cle


def langue_active(request):
    """Langue courante de la requête (session, puis cookie, puis défaut)."""
    from django.utils.translation import activate
    langue = request.session.get('langue') or request.COOKIES.get('mukmap_langue') or LANGUE_PAR_DEFAUT
    if langue not in dict(LANGUES):
        langue = LANGUE_PAR_DEFAUT
    activate(langue)
    return langue


